// Stand-in for the product database. In a real deployment these would be SQL
// queries; the module-level state here is what the ERP/PIM sync writes to.
let revision = 1
let syncedAt = '2026-08-05T00:00:00.000Z'
let products = [
  { id: 1, name: 'Laptop', price: 999, stock: 12 },
  { id: 2, name: 'Phone', price: 699, stock: 48 },
  { id: 3, name: 'Tablet', price: 499, stock: 7 },
  { id: 4, name: 'Headphones', price: 199, stock: 130 },
  { id: 5, name: 'Watch', price: 299, stock: 21 },
]

export async function getAllProducts() {
  // Simulate database delay
  await new Promise((resolve) => setTimeout(resolve, 100))

  return products.map((product) => ({ ...product }))
}

/**
 * Bookkeeping for the last upstream sync, so views can show how fresh the
 * catalog they are rendering actually is.
 */
export async function getCatalogRevision() {
  // Simulate database delay
  await new Promise((resolve) => setTimeout(resolve, 100))

  return { revision, syncedAt }
}

/**
 * Pulls pricing / inventory / availability from the upstream ERP/PIM feed and
 * writes it back to the catalog. Real sync jobs touch thousands of SKUs, so this
 * is deliberately slow — it is the work we do not want admins waiting on.
 */
export async function syncCatalogFromUpstream() {
  await new Promise((resolve) => setTimeout(resolve, 1500))

  revision += 1
  syncedAt = new Date().toISOString()
  products = products.map((product) => ({
    ...product,
    // Stand-in for upstream deltas: prices drift, stock gets recounted.
    price: product.price + revision,
    stock: Math.max(0, product.stock - revision),
  }))

  return { revision, syncedAt }
}

