import Link from 'next/link'

import { getCatalog } from '@/lib/products'

export const metadata = {
  title: 'Inventory summary',
}

/**
 * A second view over the same cached catalog read. It has no sync control of its
 * own — invalidating the `products` tag brings this page up to date too.
 */
export default async function InventorySummaryPage() {
  const { products, revision, syncedAt } = await getCatalog()

  const units = products.reduce((total, product) => total + product.stock, 0)
  const value = products.reduce(
    (total, product) => total + product.stock * product.price,
    0
  )
  const lowStock = products.filter((product) => product.stock < 10)

  return (
    <main
      style={{
        maxWidth: '52rem',
        margin: '0 auto',
        padding: '2.5rem 1.5rem',
        fontFamily: 'system-ui, sans-serif',
        color: '#18181b',
      }}
    >
      <h1 style={{ fontSize: '1.5rem', margin: 0 }}>Inventory summary</h1>
      <p style={{ margin: '0.375rem 0 0', fontSize: '0.8125rem', color: '#71717a' }}>
        revision {revision} · last synced <time dateTime={syncedAt}>{syncedAt}</time>
      </p>

      <dl style={{ display: 'flex', gap: '2.5rem', margin: '1.75rem 0' }}>
        <div>
          <dt style={{ fontSize: '0.75rem', color: '#71717a' }}>Units on hand</dt>
          <dd style={{ margin: '0.25rem 0 0', fontSize: '1.5rem' }}>{units}</dd>
        </div>
        <div>
          <dt style={{ fontSize: '0.75rem', color: '#71717a' }}>Stock value</dt>
          <dd style={{ margin: '0.25rem 0 0', fontSize: '1.5rem' }}>
            ${value.toLocaleString('en-US')}
          </dd>
        </div>
        <div>
          <dt style={{ fontSize: '0.75rem', color: '#71717a' }}>Low stock</dt>
          <dd style={{ margin: '0.25rem 0 0', fontSize: '1.5rem' }}>
            {lowStock.length}
          </dd>
        </div>
      </dl>

      <Link href="/products" style={{ fontSize: '0.875rem' }}>
        ← Back to catalog
      </Link>
    </main>
  )
}

